fn_order_transition_allowed.def:
CREATE OR REPLACE FUNCTION public.order_transition_allowed(p_from text, p_to text, p_is_admin boolean, p_is_owner boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_from = p_to THEN RETURN true; END IF;

  IF p_is_admin THEN
    CASE
      WHEN (p_from = 'pending'            AND p_to = 'confirmed') THEN RETURN true;
      WHEN (p_from = 'confirmed'          AND p_to = 'preparing') THEN RETURN true;
      WHEN (p_from = 'preparing'          AND p_to = 'ready_for_dispatch') THEN RETURN true;
      WHEN (p_from = 'ready_for_dispatch' AND p_to = 'dispatched') THEN RETURN true;
      WHEN (p_from = 'dispatched'         AND p_to = 'in_transit') THEN RETURN true;
      WHEN (p_from = 'in_transit'         AND p_to = 'arrived') THEN RETURN true;
      WHEN (p_from = 'arrived'            AND p_to = 'delivered') THEN RETURN true;
      WHEN (p_from IN ('pending','confirmed','preparing','ready_for_dispatch','dispatched','in_transit','arrived') AND p_to = 'cancelled') THEN RETURN true;
      WHEN (p_from IN ('pending','confirmed','preparing','ready_for_dispatch','dispatched','in_transit','arrived') AND p_to = 'failed') THEN RETURN true;
      ELSE RETURN false; -- F-1: off-allow-list admin transitions return false (were: case not found)
    END CASE;
    RETURN false;
  END IF;

  -- Customer (owner): can only cancel their own order from pending
  IF p_is_owner THEN
    IF p_from = 'pending' AND p_to = 'cancelled' THEN RETURN true; END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$function$

fn_enforce_operating_hours.def:
CREATE OR REPLACE FUNCTION public.enforce_operating_hours()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open      jsonb;
  v_mode_open boolean;
  v_round_key text;
BEGIN
  SELECT COALESCE(value, '{}'::jsonb) INTO v_open
    FROM public.business_settings WHERE key = 'operating_hours';

  IF v_open ? 'same_day_open' OR v_open ? 'pre_order_open' THEN
    v_mode_open := CASE WHEN NEW.order_mode::text = 'PRE_ORDER'
                        THEN COALESCE((v_open->>'pre_order_open')::boolean, true)
                        ELSE COALESCE((v_open->>'same_day_open')::boolean, true) END;
    IF NOT v_mode_open THEN
      RAISE EXCEPTION 'ERR_ORDER_MODE_CLOSED: % is currently closed', NEW.order_mode::text;
    END IF;
  END IF;

  SELECT COALESCE(round_key, name) INTO v_round_key
    FROM public.delivery_rounds WHERE id = NEW.delivery_round_id;
  IF v_round_key IS NOT NULL AND v_open ? (v_round_key || '_open') THEN
    IF COALESCE((v_open->>((v_round_key) || '_open'))::boolean, true) = false THEN
      RAISE EXCEPTION 'ERR_ROUND_CLOSED: % round is currently closed', v_round_key;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

fn_enforce_pre_order_window.def:
CREATE OR REPLACE FUNCTION public.enforce_pre_order_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today     date;
  v_now_ts    timestamp;
  v_max_days  integer;
  v_start     time;
  v_cutoff_ts timestamp;
BEGIN
  IF NEW.order_mode::text <> 'PRE_ORDER' THEN
    RETURN NEW;
  END IF;

  v_today  := (now() AT TIME ZONE 'Asia/Bangkok')::date;
  v_now_ts := (now() AT TIME ZONE 'Asia/Bangkok')::timestamp;

  -- scheduled_date must be strictly future (today/past pre-orders rejected)
  IF NEW.scheduled_date IS NULL OR NEW.scheduled_date <= v_today THEN
    RAISE EXCEPTION 'ERR_PRE_ORDER_DATE_INVALID';
  END IF;

  -- owner decision Q1: max window (business_settings, default 40)
  v_max_days := COALESCE(public.order_setting('preorder_max_days', 40), 40);
  IF (NEW.scheduled_date - v_today) > v_max_days THEN
    RAISE EXCEPTION 'ERR_PRE_ORDER_DATE_TOO_FAR: max % days ahead', v_max_days;
  END IF;

  -- owner decision Q1 cutoff: closes 2h before the round's delivery_start
  SELECT COALESCE(delivery_start, cutoff_time) INTO v_start
    FROM public.delivery_rounds
   WHERE id = NEW.delivery_round_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_ROUND_NOT_FOUND'; END IF;
  IF v_start IS NULL THEN
    RAISE EXCEPTION 'ERR_PRE_ORDER_CUTOFF_UNKNOWN';
  END IF;

  v_cutoff_ts := NEW.scheduled_date::timestamp + (v_start - interval '2 hours');
  IF v_now_ts > v_cutoff_ts THEN
    RAISE EXCEPTION 'ERR_PRE_ORDER_CUTOFF_PASSED: closes %', v_cutoff_ts;
  END IF;

  RETURN NEW;
END;
$function$

fn_driver_login.def:
CREATE OR REPLACE FUNCTION public.driver_login(p_phone text, p_name text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_drv public.drivers%ROWTYPE;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL AND current_setting('request.jwt.claims', true) IS NOT NULL THEN
    RAISE EXCEPTION 'ERR_NOT_AUTHENTICATED';
  END IF;
  IF p_phone IS NULL OR trim(p_phone) = '' THEN RAISE EXCEPTION 'ERR_MISSING_DRIVER_INFO'; END IF;

  SELECT * INTO v_drv FROM public.drivers WHERE phone = trim(p_phone);
  IF NOT FOUND THEN
    INSERT INTO public.drivers (id, name, phone, status, last_seen_at, created_at, updated_at)
    VALUES (
      'drv-' || to_char(EXTRACT(EPOCH FROM clock_timestamp()) * 1000, '99999999999') || '-' || substr(md5(random()::text), 1, 4),
      COALESCE(NULLIF(trim(p_name), ''), 'Rider'), trim(p_phone), 'available', NOW(), NOW(), NOW()
    )
    RETURNING * INTO v_drv;
  ELSE
    UPDATE public.drivers
       SET status = CASE WHEN v_drv.status = 'busy' THEN 'busy' ELSE 'available' END,
           last_seen_at = NOW(), updated_at = NOW()
     WHERE id = v_drv.id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'driver', to_jsonb(v_drv));
END;
$function$

fn_driver_accept.def:
CREATE OR REPLACE FUNCTION public.driver_accept_assignment(p_order_number text, p_driver_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_drv public.drivers%ROWTYPE;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL AND current_setting('request.jwt.claims', true) IS NOT NULL THEN
    RAISE EXCEPTION 'ERR_NOT_AUTHENTICATED';
  END IF;
  IF p_order_number IS NULL OR trim(p_order_number) = '' OR p_driver_phone IS NULL OR trim(p_driver_phone) = '' THEN
    RAISE EXCEPTION 'ERR_MISSING_DRIVER_INFO';
  END IF;
  SELECT * INTO v_drv FROM public.drivers WHERE phone = trim(p_driver_phone);
  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_DRIVER_NOT_FOUND'; END IF;

  UPDATE public.delivery_assignments
     SET status = 'accepted', accepted_at = COALESCE(accepted_at, NOW()), updated_at = NOW()
   WHERE order_number = p_order_number AND driver_id = v_drv.id AND status = 'assigned';
  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_ASSIGNMENT_NOT_ACCEPTABLE'; END IF;

  UPDATE public.drivers SET status = 'busy', last_seen_at = NOW(), updated_at = NOW() WHERE id = v_drv.id;
  RETURN jsonb_build_object('ok', true, 'order_number', p_order_number, 'status', 'accepted');
END;
$function$

fn_confirm_offline.def:
CREATE OR REPLACE FUNCTION public.confirm_offline_payment(p_order_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_method  text;
  v_order_status    public.order_status;
  v_intent_status   text;
  v_intent_id       text;
  v_paid_status     public.payment_status;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ERR_FORBIDDEN'; END IF;
  IF p_order_number IS NULL OR trim(p_order_number) = '' THEN
    RAISE EXCEPTION 'ERR_MISSING_ORDER';
  END IF;

  SELECT payment_status INTO v_paid_status
    FROM public.orders WHERE order_number = p_order_number;
  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_ORDER_NOT_FOUND'; END IF;
  IF v_paid_status = 'paid' THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'order_number', p_order_number);
  END IF;

  SELECT payment_method, status INTO v_payment_method, v_order_status
    FROM public.orders WHERE order_number = p_order_number;

  IF v_payment_method = 'cash_on_delivery' THEN
    IF v_order_status <> 'delivered' THEN
      RAISE EXCEPTION 'ERR_COD_NOT_DELIVERED';
    END IF;
    UPDATE public.payment_intents
       SET status = 'completed', completed_at = NOW(), updated_at = NOW()
     WHERE order_number = p_order_number AND method = 'cash_on_delivery';
  ELSE
    SELECT status, id INTO v_intent_status, v_intent_id
      FROM public.payment_intents
     WHERE order_number = p_order_number AND method = v_payment_method
     ORDER BY created_at DESC LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'ERR_NO_PAYMENT_INTENT'; END IF;
    IF v_intent_status <> 'processing' THEN
      RAISE EXCEPTION 'ERR_INTENT_NOT_PROCESSING';
    END IF;
    UPDATE public.payment_intents
       SET status = 'completed', completed_at = NOW(), updated_at = NOW()
     WHERE id = v_intent_id;
  END IF;

  UPDATE public.orders
     SET payment_status = 'paid', updated_at = NOW()
   WHERE order_number = p_order_number;

  PERFORM public.append_audit_log(
    p_action := 'payment_processed',
    p_entity_type := 'order',
    p_entity_id := p_order_number,
    p_description := 'payment confirmed (' || v_payment_method || ')',
    p_metadata := jsonb_build_object('payment_method', v_payment_method, 'payment_status', 'paid')
  );

  RETURN jsonb_build_object('ok', true, 'idempotent', false, 'order_number', p_order_number, 'payment_status', 'paid');
END;
$function$

fn_record_payment.def:
CREATE OR REPLACE FUNCTION public.record_payment_result(p_order_number text, p_payment_intent_id text, p_amount numeric, p_currency text DEFAULT 'thb'::text, p_status text DEFAULT 'completed'::text, p_failure_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_total numeric;
  v_existing text;
  v_new_payment_status text;
  v_target_id text;
BEGIN
  IF p_order_number IS NULL OR trim(p_order_number) = '' THEN
    RAISE EXCEPTION 'ERR_MISSING_ORDER';
  END IF;
  IF p_payment_intent_id IS NULL OR trim(p_payment_intent_id) = '' THEN
    RAISE EXCEPTION 'ERR_MISSING_PAYMENT_INTENT_ID';
  END IF;

  -- Idempotency (010): only a terminal result recorded for this PaymentIntent
  -- short-circuits. A still-pending row (created by create-checkout) must NOT
  -- look like a replay, otherwise the first real webhook delivery never applies.
  SELECT status INTO v_existing
    FROM public.payment_intents
   WHERE payment_intent_id = p_payment_intent_id
     AND status IN ('completed', 'failed');
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'order_number', p_order_number,
      'payment_status', (SELECT payment_status FROM public.orders WHERE order_number = p_order_number),
      'intent_status', v_existing
    );
  END IF;

  -- Authoritative amount check.
  SELECT total_amount INTO v_order_total
    FROM public.orders
   WHERE order_number = p_order_number;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ERR_ORDER_NOT_FOUND';
  END IF;
  IF COALESCE(p_amount, -1) <> v_order_total THEN
    RAISE EXCEPTION 'ERR_AMOUNT_MISMATCH';
  END IF;

  v_new_payment_status := CASE
    WHEN p_status = 'completed' THEN 'paid'
    WHEN p_status = 'failed'    THEN 'pending'
    ELSE 'pending'
  END;

  -- PHASE 3A: target EXACTLY ONE attempt row (never blanket-update the order's rows,
  -- never violate uq_payment_intents_provider_id on retried payments).
  SELECT id INTO v_target_id
    FROM public.payment_intents
   WHERE order_number = p_order_number
     AND (payment_intent_id = p_payment_intent_id OR payment_intent_id IS NULL)
   ORDER BY (payment_intent_id = p_payment_intent_id) DESC, created_at ASC
   LIMIT 1;
  IF v_target_id IS NULL THEN
    RAISE EXCEPTION 'ERR_NO_PAYMENT_INTENT';
  END IF;

  UPDATE public.payment_intents
     SET status            = p_status,
         payment_intent_id = COALESCE(payment_intent_id, p_payment_intent_id),
         amount            = p_amount,
         currency          = p_currency,
         failure_reason    = COALESCE(p_failure_reason, failure_reason),
         completed_at      = CASE WHEN p_status = 'completed' THEN NOW() ELSE completed_at END,
         updated_at        = NOW()
   WHERE id = v_target_id;

  UPDATE public.orders
     SET payment_status = v_new_payment_status::payment_status,
         updated_at     = NOW()
   WHERE order_number = p_order_number;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'order_number', p_order_number,
    'payment_status', v_new_payment_status
  );
END;
$function$

fn_create_order_head.def:
CREATE OR REPLACE FUNCTION public.create_order_with_items(p_items jsonb, p_delivery_round_id text, p_delivery_method text DEFAULT 'self_delivery'::text, p_delivery_address text DEFAULT ''::text, p_dropoff_latitude numeric DEFAULT NULL::numeric, p_dropoff_longitude numeric DEFAULT NULL::numeric, p_customer_name text DEFAULT ''::text, p_customer_phone text DEFAULT ''::text, p_payment_method text DEFAULT 'promptpay_qr'::text, p_special_instructions text DEFAULT ''::text, p_promotion_code text DEFAULT NULL::text, p_distance_km numeric DEFAULT 0, p_order_mode text DEFAULT 'SAME_DAY'::text, p_scheduled_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid            uuid;
  v_order_id       text;
  v_order_number   text;
  v_order_exists   boolean;
  v_attempt        integer := 0;
  v_mode           text;
  v_item_row       record;
  v_pid            text;
  v_qty            integer;
  v_unit_price     numeric;
  v_addon_price    numeric;
  v_item_sub       numeric;
  v_subtotal       numeric := 0;
  v_discount       numeric := 0;
  v_delivery_fee   numeric := 0;
  v_service_fee    numeric := 0;
  v_tax            numeric := 0;
  v_total          numeric := 0;
  v_items_total_qty integer := 0;
  v_round_status   text;
  v_max_cap        integer;
  v_cur_count      integer;
  v_round_date     date;
  v_round_cutoff   time;
  v_prod_is_avail  boolean;
  v_prod_same_day  boolean;
  v_prod_preorder  boolean;
  v_prod_name      text;
  v_delivery_method text;
  v_distance       numeric;
  v_promo          public.promotions%ROWTYPE;
  v_ing_name       text;
  v_today          date := (now() AT TIME ZONE 'Asia/Bangkok')::date;
  v_now            time := (now() AT TIME ZONE 'Asia/Bangkok')::time;
BEGIN
  -- ===== 1. AUTHENTICATION =====
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ERR_NOT_AUTHENTICATED';
  END IF;

  -- ===== 2. ORDER MODE + INPUT =====
  v_mode := COALESCE(p_order_mode, 'SAME_DAY');
  IF v_mode NOT IN ('SAME_DAY', 'PRE_ORDER') THEN
    RAISE EXCEPTION 'ERR_INVALID_ORDER_MODE';
  END IF;
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'ERR_EMPTY_ORDER';
  END IF;
  IF p_delivery_round_id IS NULL OR trim(p_delivery_round_id) = '' THEN
    RAISE EXCEPTION 'ERR_MISSING_ROUND';
  END IF;
  IF p_payment_method NOT IN ('promptpay_qr', 'cash_on_delivery', 'credit_card') THEN
    RAISE EXCEPTION 'ERR_INVALID_PAYMENT_METHOD';
  END IF;
  IF p_delivery_method NOT IN ('self_delivery', 'grab_rider', 'linemen_rider', 'foodpanda_rider') THEN
    RAISE EXCEPTION 'ERR_INVALID_DELIVERY_METHOD';
  END IF;

  -- ===== 3. DELIVERY ROUND — atomic capacity lock =====
  SELECT status, max_capacity, current_count, scheduled_date, cutoff_time
    INTO v_round_status, v_max_cap, v_cur_count, v_round_date, v_round_cutoff
    FROM public.delivery_rounds
   WHERE id = p_delivery_round_id
   FOR UPDATE;

  IF v_round_status IS NULL THEN
    RAISE EXCEPTION 'ERR_ROUND_NOT_FOUND';
  END IF;
  IF v_round_status <> 'active' THEN
    RAISE EXCEPTION 'ERR_ROUND_CLOSED';
  END IF;

  -- ===== 4. MODE-SPECIFIC ROUND / CUTOFF / DATE RULES (server authority, Bangkok time) =====
  IF v_mode = 'SAME_DAY' THEN
    IF v_round_date IS NULL OR v_round_date <> v_today THEN
      RAISE EXCEPTION 'ERR_ROUND_DATE';
    END IF;
    IF v_now > v_round_cutoff THEN
      RAISE EXCEPTION 'ERR_CUTOFF_PASSED';
    END IF;
    IF p_scheduled_date IS NOT NULL AND p_scheduled_date <> v_round_date THEN
      RAISE EXCEPTION 'ERR_ROUND_DATE';
    END IF;
  ELSE
    IF p_scheduled_date IS NULL THEN
      RAISE EXCEPTION 'ERR_MISSING_SCHEDULED_DATE';
    END IF;
    IF p_scheduled_date <= v_today THEN
      RAISE EXCEPTION 'ERR_SCHEDULED_DATE_INVALID';
    END IF;
    IF p_scheduled_date <> v_round_date THEN
      RAISE EXCEPTION 'ERR_ROUND_DATE_MISMATCH';
    END IF;
    IF (p_scheduled_date - v_today) < public.order_setting('pre_order_lead_days', 1) THEN
      RAISE EXCEPTION 'ERR_LEAD_TIME';
    END IF;
  END IF;

  -- capacity check (1 order = 1 slot; +1 handled by trigger orders_increment_round)
  IF (COALESCE(v_cur_count, 0) + 1) > v_max_cap THEN
    RAISE EXCEPTION 'ERR_CAPACITY_FULL';
  END IF;

  -- ===== 5. PRODUCTS — authoritative prices + MODE GATE (both directions) =====
  FOR v_item_row IN SELECT * FROM jsonb_to_recordset(p_items)
      AS x(product_id text, quantity integer, options jsonb, special_request text)
  LOOP
    v_pid := v_item_row.product_id;
    v_qty := COALESCE(v_item_row.quantity, 0);

    IF v_pid IS NULL OR trim(v_pid) = '' THEN
      RAISE EXCEPTION 'ERR_MISSING_PRODUCT_ID';
    END IF;
    IF v_qty <= 0 OR v_qty > 1000 THEN
      RAISE EXCEPTION 'ERR_INVALID_QUANTITY';
    END IF;

    SELECT price, is_available, available_same_day, available_preorder, name
      INTO v_unit_price, v_prod_is_avail, v_prod_same_day, v_prod_preorder, v_prod_name
      FROM public.products
     WHERE id = v_pid
     FOR UPDATE;

    IF v_unit_price IS NULL THEN
      RAISE EXCEPTION 'ERR_PRODUCT_NOT_FOUND';
    END IF;
    IF NOT COALESCE(v_prod_is_avail, false) THEN
      RAISE EXCEPTION 'ERR_PRODUCT_UNAVAILABLE';
    END IF;

    -- INVARIANT 1: mode gate, server-authoritative (client UI is NOT authority)
    IF v_mode = 'SAME_DAY' AND NOT COALESCE(v_prod_same_day, false) THEN
      RAISE EXCEPTION 'ERR_PRODUCT_MODE_NOT_ALLOWED';
    END IF;
    IF v_mode = 'PRE_ORDER' AND NOT COALESCE(v_prod_preorder, false) THEN
      RAISE EXCEPTION 'ERR_PRODUCT_MODE_NOT_ALLOWED';
    END IF;

    -- add-on surcharge re-derived from products.addons (client sends no prices)
    v_addon_price := public.compute_addons_price(v_pid, v_item_row.options);

    v_item_sub := v_qty * (v_unit_price + COALESCE(v_addon_price, 0));
    v_subtotal := v_subtotal + v_item_sub;
